#include <iostream>
#include <vector>
using namespace std;

const int MAX_SIZE = 250010;
long long fact[MAX_SIZE], invFact[MAX_SIZE];
long long dpStates[30][MAX_SIZE];
int bitsCount[MAX_SIZE];
long long totalCount, maxLimit, modVal;

long long choose(int n, int r) {
    return fact[n] * invFact[n - r] % modVal * invFact[r] % modVal;
}

void add_value(long long &x, long long y) {
    x += y;
    if (x >= modVal) x -= modVal;
}

int main() {
    cin >> totalCount >> maxLimit >> modVal;
    fact[0] = invFact[0] = 1;
    fact[1] = invFact[1] = 1;
    for (int i = 2; i <= totalCount; i++) {
        int q = modVal / i;
        int r = modVal - i * q;
        fact[i] = fact[i - 1] * i % modVal;
        invFact[i] = modVal - (long long)q * invFact[r] % modVal;
    }
    for (int i = 2; i <= totalCount; i++) {
        invFact[i] = invFact[i - 1] * invFact[i] % modVal;
    }
    long long result = 1;
    for (int i = 1; i <= totalCount; i++) result = result * maxLimit % modVal;
    for (int i = 1; i <= totalCount; i++) bitsCount[i] = bitsCount[i >> 1] + (i & 1);
    if (totalCount & 1) {
        cout << result << endl;
        return 0;
    }
    dpStates[0][0] = 1;
    int maxBits = min(bitsCount[totalCount], maxLimit);
    for (int i = 0; i < maxBits; i++) {
        for (int j = 0; j < totalCount; j++) {
            if (dpStates[i][j] == 0) continue;
            int mask = totalCount ^ j;
            for (int k = mask, r; k > j; k = (k - 1) & mask) {
                r = k | j;
                add_value(dpStates[i + 1][r], dpStates[i][j] * invFact[k]);
            }
        }
    }
    for (int i = 1; i <= maxLimit; i++) {
        result -= dpStates[i][totalCount] * fact[maxLimit] % modVal * invFact[maxLimit - i] % modVal * fact[totalCount] % modVal;
    }
    result = (modVal + result % modVal) % modVal;
    cout << result << endl;
    return 0;
}
